method Count(strings: seq<string>, prefix: string) returns (count: int)
    requires strings != null
    requires forall i :: 0 <= i < |strings| ==> strings[i] != null
    requires prefix != null
    ensures count == |{ i | 0 <= i < |strings| && strings[i].StartsWith(prefix) }|
{
    count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant count == |{ j | 0 <= j < i && strings[j].StartsWith(prefix) }|
